import{_ as o,I as n,c as r,o as e,a3 as a,b as s,w as l,a as d,J as E,a4 as c}from"./chunks/framework.MI-M1z4O.js";const b=JSON.parse('{"title":"[特許ホワイトペーパー] 仕様ベース4段階ウィザードおよびビルド自己修復システム","description":"AIコーディングエージェントのハルシネーションを防止する4段階仕様ウィザードと、コンパイラエラーの逆フィードバックに基づくビルド自己修復技術ホワイトペーパー","frontmatter":{"title":"[特許ホワイトペーパー] 仕様ベース4段階ウィザードおよびビルド自己修復システム","shortTitle":"[第07号] 4段階ウィザード & ビルド修復","category":"コア技術 & 特許","sort":3,"description":"AIコーディングエージェントのハルシネーションを防止する4段階仕様ウィザードと、コンパイラエラーの逆フィードバックに基づくビルド自己修復技術ホワイトペーパー","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/patents/07-four-stage-wizard-build"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/patents/07-four-stage-wizard-build"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/patents/07-four-stage-wizard-build"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/patents/07-four-stage-wizard-build"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/patents/07-four-stage-wizard-build"}]]},"headers":[],"relativePath":"ja/patents/07-four-stage-wizard-build.md","filePath":"ja/patents/07-four-stage-wizard-build.md","lastUpdated":1795293539000}'),g={name:"ja/patents/07-four-stage-wizard-build.md"};function A(f,t,p,h,u,B){const i=n("Mermaid");return e(),r("div",null,[t[1]||(t[1]=a('<h1 id="仕様ベース4段階ウィザードおよびビルド自己修復システム" tabindex="-1">仕様ベース4段階ウィザードおよびビルド自己修復システム <a class="header-anchor" href="#仕様ベース4段階ウィザードおよびビルド自己修復システム" aria-label="Permalink to “仕様ベース4段階ウィザードおよびビルド自己修復システム”">​</a></h1><blockquote><p><strong>特許出願管理番号</strong>: 第07号<br><strong>発明の名称</strong>: 仕様ベース4段階ウィザードおよびビルドアーティファクト検証フィードバックループを用いたソースコード自律変異および自己修復（Self-Healing）システム・方法<br><strong>出願管理状態</strong>: 出願準備（早期審査対象、登録可能性Aランク評価）<br><strong>連携プロダクト</strong>: <code>SyncBoot</code>, <code>SyncVerse</code></p></blockquote><hr><h2 id="_1-解決しようとする技術的課題" tabindex="-1">1. 解決しようとする技術的課題 <a class="header-anchor" href="#_1-解決しようとする技術的課題" aria-label="Permalink to “1. 解決しようとする技術的課題”">​</a></h2><p>大規模言語モデル（LLM）ベースのコーディングツール（例: GitHub Copilot、一般的なAIコーディングアシスタント）は、自然言語プロンプトをもとにソースコードを迅速に作成できますが、既存コードベース全体のコンテキストや依存関係を完全に把握できないという限界があります。</p><p>これにより、以下のような深刻なソフトウェア工学上の欠陥が発生します。</p><ol><li><strong>ハルシネーションに基づくコード生成</strong>: 実際には存在しないサードパーティパッケージやクラスメソッドを無断で呼び出し、コンパイルエラーを引き起こします。</li><li><strong>見せかけの正常（Fake Fallback）コードのコミット</strong>: ビジネスロジックを完全に実装せず、空のスタブメソッド（<code>return null;</code> など）を生成して単体テストを欺きます。</li><li><strong>ビルド失敗アーティファクトの放置</strong>: パッチ適用後にコンパイルエラーやテスト失敗が発生してもそれを検知せず、そのままコミットしてCI/CDパイプラインを麻痺させます。</li></ol>',7)),(e(),s(c,null,{default:l(()=>[E(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Req%5B%22%E8%87%AA%E7%84%B6%E8%A8%80%E8%AA%9E%E8%A6%81%E4%BB%B6%E3%81%AE%E5%85%A5%E5%8A%9B%22%5D%20--%3E%20S1%5B%22Step%201%3A%20%E3%82%B3%E3%83%BC%E3%83%89%E3%83%99%E3%83%BC%E3%82%B9%E5%AE%9F%E6%B8%AC%E3%81%8A%E3%82%88%E3%81%B3%E4%BE%9D%E5%AD%98%E9%96%A2%E4%BF%82%E8%A7%A3%E6%9E%90%22%5D%0A%20%20%20%20S1%20--%3E%20S2%5B%22Step%202%3A%20%E6%A9%9F%E8%83%BD%E4%BB%95%E6%A7%98%E3%81%8A%E3%82%88%E3%81%B3%E3%82%A8%E3%83%B3%E3%83%89%E3%83%9D%E3%82%A4%E3%83%B3%E3%83%88%E5%AE%9A%E7%BE%A9%22%5D%0A%20%20%20%20S2%20--%3E%20S3%5B%22Step%203%3A%20DDL%E3%82%B9%E3%82%AD%E3%83%BC%E3%83%9E%20%26%20focusFiles%20%E9%9A%94%E9%9B%A2%E8%A8%88%E7%94%BB%22%5D%0A%20%20%20%20S3%20--%3E%20S4%5B%22Step%204%3A%20AtomicDiffPatchEngine%20%E3%81%AB%E3%82%88%E3%82%8B%E3%82%BD%E3%83%BC%E3%82%B9%E5%A4%89%E7%95%B0%22%5D%0A%20%20%20%20S4%20--%3E%20Build%7B%22%E5%AE%9F%E3%83%90%E3%83%83%E3%82%AF%E3%82%A8%E3%83%B3%E3%83%89%E3%83%93%E3%83%AB%E3%83%89%E3%81%8A%E3%82%88%E3%81%B3%E5%8D%98%E4%BD%93%E3%83%86%E3%82%B9%E3%83%88%E6%A4%9C%E8%A8%BC%22%7D%0A%20%20%20%20Build%20--%20%22%E3%83%93%E3%83%AB%E3%83%89%E6%88%90%E5%8A%9F%20(Pass)%22%20--%3E%20PR%5B%22%E6%A4%9C%E8%A8%BC%E5%AE%8C%E4%BA%86PR%E3%81%AE%E8%87%AA%E5%8B%95%E7%99%BA%E8%A1%8C%22%5D%0A%20%20%20%20Build%20--%20%22%E3%82%B3%E3%83%B3%E3%83%91%E3%82%A4%E3%83%AB%2F%E3%83%86%E3%82%B9%E3%83%88%E5%A4%B1%E6%95%97%22%20--%3E%20Feedback%5B%22%E3%82%B3%E3%83%B3%E3%83%91%E3%82%A4%E3%83%A9%E3%82%A8%E3%83%A9%E3%83%BC%E3%83%AD%E3%82%B0%20%26%20%E5%A4%B1%E6%95%97%E7%AE%87%E6%89%80%E3%82%BD%E3%83%BC%E3%82%B9%E3%81%AE%E6%8A%BD%E5%87%BA%22%5D%0A%20%20%20%20Feedback%20--%3E%20Repair%5B%22%E8%87%AA%E5%B7%B1%E4%BF%AE%E5%BE%A9%E3%83%AB%E3%83%BC%E3%83%97%20(autoRepairCode)%22%5D%0A%20%20%20%20Repair%20--%3E%7C%22%E6%9C%80%E5%A4%A73%E3%80%9C5%E5%9B%9E%E5%8F%8D%E5%BE%A9%22%7C%20S4%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<hr><h2 id="_2-4段階仕様ウィザードパイプライン" tabindex="-1">2. 4段階仕様ウィザードパイプライン <a class="header-anchor" href="#_2-4段階仕様ウィザードパイプライン" aria-label="Permalink to “2. 4段階仕様ウィザードパイプライン”">​</a></h2><p>本発明は、自然言語の指示を直ちにコードへ変換するのではなく、4段階の段階的ウィザードパイプラインを経由させることを強制し、ハルシネーションの発生可能性を構造的に抑制します。</p><h3 id="step-1-コードベース実測-grounding-analysis" tabindex="-1">Step 1: コードベース実測（Grounding Analysis） <a class="header-anchor" href="#step-1-コードベース実測-grounding-analysis" aria-label="Permalink to “Step 1: コードベース実測（Grounding Analysis）”">​</a></h3><ul><li>現在のリポジトリのソースコードツリー、Maven/Gradle依存ライブラリ一覧、既定義のエンティティおよびDTOスキーマを静的解析します。</li><li>変更作業に必要なプロジェクトコンテキスト（使用中のSpring Bootバージョン、依存ライブラリのバージョンなど）を客観的データとして確保します。</li></ul><h3 id="step-2-機能および画面仕様の導出-specification-definition" tabindex="-1">Step 2: 機能および画面仕様の導出（Specification Definition） <a class="header-anchor" href="#step-2-機能および画面仕様の導出-specification-definition" aria-label="Permalink to “Step 2: 機能および画面仕様の導出（Specification Definition）”">​</a></h3><ul><li>ユーザーの要件をビジネスルール、入力検証条件、認可権限要件へと細分化します。</li><li>実装対象となるRESTful API仕様（エンドポイントURI、HTTP Method、Request/Response JSONスキーマ）を宣言的なドキュメント形式で先行確定します。</li></ul><h3 id="step-3-ddlスキーマおよび-focusfiles-計画策定-plan-scope-isolation" tabindex="-1">Step 3: DDLスキーマおよび focusFiles 計画策定（Plan &amp; Scope Isolation） <a class="header-anchor" href="#step-3-ddlスキーマおよび-focusfiles-計画策定-plan-scope-isolation" aria-label="Permalink to “Step 3: DDLスキーマおよび focusFiles 計画策定（Plan &amp; Scope Isolation）”">​</a></h3><ul><li>変更対象のデータベースDDLスクリプトを作成します。</li><li>リポジトリ全体のうち、実際に修正が必要なファイル一覧を <code>focusFiles</code> 配列として厳格に限定し、不要なグローバルソースコードの汚染を防止します。</li></ul><h3 id="step-4-アトミックdiffパッチ適用-atomic-code-mutation" tabindex="-1">Step 4: アトミックDiffパッチ適用（Atomic Code Mutation） <a class="header-anchor" href="#step-4-アトミックdiffパッチ適用-atomic-code-mutation" aria-label="Permalink to “Step 4: アトミックDiffパッチ適用（Atomic Code Mutation）”">​</a></h3><ul><li><code>AtomicDiffPatchEngine</code> を使用し、指定された <code>focusFiles</code> に対してのみ変更差分（Diff）を行単位で精密に注入します。</li><li>既存ファイル全体を上書きせず変更ブロックのみを置換するため、既存のコメントおよびコーディング規約の毀損を最小限に抑えます。</li></ul><hr><h2 id="_3-コンパイラエラー逆フィードバックに基づくビルド自己修復ループ" tabindex="-1">3. コンパイラエラー逆フィードバックに基づくビルド自己修復ループ <a class="header-anchor" href="#_3-コンパイラエラー逆フィードバックに基づくビルド自己修復ループ" aria-label="Permalink to “3. コンパイラエラー逆フィードバックに基づくビルド自己修復ループ”">​</a></h2><p>パッチが適用された直後、システムは隔離されたサンドボックス環境で実際のコンパイラ（<code>javac</code>、<code>mvn test-compile</code>）およびテストランナーを実行し、ビルドアーティファクトを実測検証します。</p><ol><li><strong>エラー追跡およびコンテキスト再合成</strong>: <ul><li>ビルド失敗が発生した場合、コンパイラが出力した正確なエラーメッセージ、ソースファイル名、行番号、シンボル未認識（Cannot find symbol）などの標準エラー出力を抽出します。</li></ul></li><li><strong>エージェントへの逆フィードバック（<code>autoRepairCode</code>）</strong>: <ul><li>抽出されたエラーログと失敗箇所のソースコードをエージェントの自己修復モジュールへ再注入します。</li><li>エージェントは不足している <code>import</code> 文の追加、メソッドシグネチャの整合性調整、型キャストエラーの修正など、コンパイル通過に必要な最小限の変更パッチを再合成します。</li></ul></li><li><strong>反復閾値および安全終了</strong>: <ul><li>自己修復ループは最大3回から5回以内に制限されます。</li><li>すべてのコンパイルおよび単体テストを完全に通過した場合にのみ有効なPR（Pull Request）を生成し、閾値を超過した場合は作業内容をロールバックして管理者に原因分析レポートを通知します。</li></ul></li></ol><hr><h2 id="_4-先行技術との定量的比較" tabindex="-1">4. 先行技術との定量的比較 <a class="header-anchor" href="#_4-先行技術との定量的比較" aria-label="Permalink to “4. 先行技術との定量的比較”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">比較項目</th><th style="text-align:left;">一般的なAIコーディングアシスタント</th><th style="text-align:left;">静的テンプレートコード生成器</th><th style="text-align:left;">本特許システム（07号）</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>コード生成方式</strong></td><td style="text-align:left;">単一プロンプトによる一括生成</td><td style="text-align:left;">固定されたスキャフォールディングテンプレート</td><td style="text-align:left;"><strong>4段階ウィザードによる段階的詳細化</strong></td></tr><tr><td style="text-align:left;"><strong>コンテキストハルシネーション防止</strong></td><td style="text-align:left;">プロンプト長に依存し脆弱</td><td style="text-align:left;">コンテキスト反映不可</td><td style="text-align:left;"><strong>コードベース実測および focusFiles 隔離</strong></td></tr><tr><td style="text-align:left;"><strong>コンパイル検証</strong></td><td style="text-align:left;">未提供（人間の開発者が確認）</td><td style="text-align:left;">コンパイルは通るがビジネスロジックが欠如</td><td style="text-align:left;"><strong>実コンパイラ連携による自動検証</strong></td></tr><tr><td style="text-align:left;"><strong>ビルドエラー修復</strong></td><td style="text-align:left;">非対応</td><td style="text-align:left;">テンプレート修正が必要</td><td style="text-align:left;"><strong>コンパイラエラー逆フィードバック自己修復</strong></td></tr></tbody></table><hr><h2 id="_5-実測性能およびコードベース実装証跡" tabindex="-1">5. 実測性能およびコードベース実装証跡 <a class="header-anchor" href="#_5-実測性能およびコードベース実装証跡" aria-label="Permalink to “5. 実測性能およびコードベース実装証跡”">​</a></h2><p>社内マイクロサービスバックエンドの新規機能実装150件を対象とした実測結果は以下のとおりです。</p><ul><li><strong>初回パッチ適用後のビルド通過率</strong>: 4段階ウィザード適用時に82.6%を達成。</li><li><strong>自己修復ループ通過率</strong>: 初回ビルド失敗案件のうち、3回以内の <code>autoRepairCode</code> ループを経て最終ビルド通過率 <strong>96.8%</strong> を記録。</li><li><strong>見せかけの正常コード混入遮断</strong>: Zero-Mockテストハーネスと結合し、未実装メソッドのコミット <strong>0件を維持</strong>。</li></ul><h3 id="コードベース実装箇所-grounding" tabindex="-1">コードベース実装箇所（Grounding） <a class="header-anchor" href="#コードベース実装箇所-grounding" aria-label="Permalink to “コードベース実装箇所（Grounding）”">​</a></h3><ul><li><code>sync-module-deploy/src/main/java/com/empasy/sync/deploy/engine/AtomicDiffPatchEngine.java</code>: アトミックパッチ注入器</li><li><code>sync-boot/Server/src/main/java/com/empasy/sync/boot/generator/FourStageWizardService.java</code>: 4段階仕様ウィザードエンジン</li><li><code>sync-verse/Server/src/main/java/com/empasy/sync/verse/controller/SelfHealingRunbookController.java</code>: ビルド検証および自己修復オーケストレーター</li></ul>',24))])}const y=o(g,[["render",A]]);export{b as __pageData,y as default};
